// 1.3.0 — the helper runtime generated routes call moved out of MetaObjects.Codegen into the
// MetaObjects.AspNetCore package. HelperRuntimeReference warns when the project compiling a
// generated file that imports it does not reference that package, and stays silent otherwise.

using Xunit;

namespace MetaObjects.Codegen.Tests;

public sealed class HelperRuntimeReferenceTests : IDisposable
{
    private readonly string _tmp = Path.Combine(Path.GetTempPath(), "mo-helper-ref-" + Guid.NewGuid().ToString("N"));

    private const string Importing = "// <auto-generated/>\nusing MetaObjects.AspNetCore;\nnamespace Acme;\n";

    public HelperRuntimeReferenceTests() => Directory.CreateDirectory(_tmp);

    public void Dispose() { try { Directory.Delete(_tmp, recursive: true); } catch { } }

    private string Write(string relative, string content)
    {
        var path = Path.Combine(_tmp, relative.Replace('/', Path.DirectorySeparatorChar));
        Directory.CreateDirectory(Path.GetDirectoryName(path)!);
        File.WriteAllText(path, content);
        return path;
    }

    private static string Project(string items) =>
        $"<Project Sdk=\"Microsoft.NET.Sdk\">\n  <ItemGroup>\n    {items}\n  </ItemGroup>\n</Project>\n";

    private IReadOnlyList<string> Check(params string[] files) =>
        HelperRuntimeReference.Warnings(files.Select(f => (f, File.ReadAllText(f))));

    [Fact]
    public void A_project_without_the_package_gets_one_warning_naming_the_line_to_add()
    {
        Write("app/App.csproj", Project("<PackageReference Include=\"MetaObjects.Codegen\" Version=\"1.2.3\" />"));
        var a = Write("app/Generated/ARoutes.g.cs", Importing);
        var b = Write("app/Generated/BRoutes.g.cs", Importing);

        var warning = Assert.Single(Check(a, b));
        Assert.Contains("and 1 other generated file(s) import MetaObjects.AspNetCore", warning);
        Assert.Contains("App.csproj does not reference the MetaObjects.AspNetCore package", warning);
        Assert.Contains("<PackageReference Include=\"MetaObjects.AspNetCore\" Version=\"", warning);
    }

    [Theory]
    [InlineData("<PackageReference Include=\"MetaObjects.AspNetCore\" Version=\"1.3.0\" />")]
    [InlineData("<PackageReference Include=\"metaobjects.aspnetcore\" Version=\"1.3.0\" />")]
    [InlineData("<ProjectReference Include=\"../../server/csharp/MetaObjects.AspNetCore/MetaObjects.AspNetCore.csproj\" />")]
    public void A_direct_reference_is_enough(string item)
    {
        Write("app/App.csproj", Project(item));
        Assert.Empty(Check(Write("app/Generated/ARoutes.g.cs", Importing)));
    }

    [Fact]
    public void A_reference_through_a_referenced_project_is_enough()
    {
        Write("shared/Shared.csproj", Project("<PackageReference Include=\"MetaObjects.AspNetCore\" Version=\"1.3.0\" />"));
        Write("app/App.csproj", Project("<ProjectReference Include=\"..\\shared\\Shared.csproj\" />"));
        Assert.Empty(Check(Write("app/Generated/ARoutes.g.cs", Importing)));
    }

    [Fact]
    public void A_reference_in_a_directory_build_props_above_is_enough()
    {
        Write("Directory.Build.props", Project("<PackageReference Include=\"MetaObjects.AspNetCore\" Version=\"1.3.0\" />"));
        Write("app/App.csproj", Project(""));
        Assert.Empty(Check(Write("app/Generated/ARoutes.g.cs", Importing)));
    }

    [Fact]
    public void No_project_or_no_import_is_silent()
    {
        Assert.Empty(Check(Write("loose/ARoutes.g.cs", Importing)));
        Write("app/App.csproj", Project(""));
        Assert.Empty(Check(Write("app/Generated/Entity.g.cs", "// <auto-generated/>\nnamespace Acme;\n")));
    }

    [Fact]
    public void Output_that_still_imports_the_helpers_from_their_old_namespace_warns()
    {
        Write("app/App.csproj", Project("<PackageReference Include=\"MetaObjects.AspNetCore\" Version=\"1.3.0\" />"));
        var stale = Write("app/Generated/ARoutes.g.cs",
            "// <auto-generated/>\nusing MetaObjects.Codegen.Runtime;\nclass A { object f = FilterParser.Parse; }\n");
        var warning = Assert.Single(Check(stale));
        Assert.Contains("imports MetaObjects.Codegen.Runtime", warning);
        Assert.Contains("HelperRuntimeNamespace", warning);
    }

    [Fact]
    public void The_old_namespace_for_the_core_reply_parser_alone_is_silent()
    {
        Write("app/App.csproj", Project(""));
        Assert.Empty(Check(Write("app/Generated/Parser.g.cs",
            "// <auto-generated/>\nusing MetaObjects.Codegen.Runtime;\nclass P { object f = ExtractObject.Extract; }\n")));
    }

    [Fact]
    public void ForTrees_reads_only_generated_files_and_skips_build_output()
    {
        Write("app/App.csproj", Project(""));
        Write("app/Generated/Hand.cs", "using MetaObjects.AspNetCore;\n");
        Write("app/Generated/obj/Stale.g.cs", Importing);
        Assert.Empty(HelperRuntimeReference.ForTrees([Path.Combine(_tmp, "app", "Generated")]));

        Write("app/Generated/ARoutes.g.cs", Importing);
        var warning = Assert.Single(HelperRuntimeReference.ForTrees([Path.Combine(_tmp, "app", "Generated")], _tmp));
        Assert.StartsWith("app/Generated/ARoutes.g.cs imports", warning);
    }
}
